# Anti-pattern data, part B: keyboard and pointer, forms.
from data_a import R, S, X

KEYBOARD = [
 dict(id='AP-KBD-01', title='Positive `tabindex`', sev='major', wcag=['2.4.3'], rgaa=['12.8'], axe=['tabindex'], conf='certain', lang='html',
  what='A positive value pulls the element to the front of the Tab sequence, ahead of everything else on the page. Focus jumps around instead of following the reading order, and the effect compounds with each new value.',
  dtext='`tabindex` greater than 0 (HTML or JSX).',
  detect=[S('[tabindex]:not([tabindex="0"]):not([tabindex^="-"])'), R(r'''\btabindex\s*=\s*['"]?\{?\s*[1-9]\d*''')],
  bad='<label for="email">Email address</label>\n<input id="email" name="email" type="email" autocomplete="email" tabindex="1">\n<button type="submit" tabindex="2">Subscribe</button>',
  good='<label for="email">Email address</label>\n<input id="email" name="email" type="email" autocomplete="email">\n<button type="submit">Subscribe</button>'),
 dict(id='AP-KBD-02', title='Focus indicator removed', sev='blocking', wcag=['2.4.7'], rgaa=['10.7'], axe=[], lang='css',
  what='A sighted keyboard user who cannot see where focus is cannot use the page at all: every key press is a guess. `outline: none` in a reset style sheet is the most common single cause.',
  dtext='`outline: none` or `outline: 0` in a style sheet that defines no `:focus-visible` or `:focus` rule with a visible replacement. Confirm by tabbing through the page.',
  detect=[R(r'''outline(?:-style|-width)?\s*:\s*(?:none|0(?:px)?)\s*(?:!important)?\s*[;}]''', target='css', unless=r''':focus(?:-visible)?[^{]*\{[^}]*(?:outline\s*:\s*(?!\s|none|0\b)[^;}]+|box-shadow\s*:\s*(?!\s|none)[^;}]+|border[^:]*:\s*(?!\s|none|0\b)[^;}]+)''')],
  bad='button:focus { outline: none; }',
  good='button:focus-visible {\n  outline: 3px solid currentColor;\n  outline-offset: 2px;\n}'),
 dict(id='AP-KBD-03', title='Content revealed on hover only', sev='blocking', wcag=['2.1.1'], rgaa=['10.14', '12.11'], axe=[], lang='css',
  what='A sub-menu, a card action or a help bubble that appears on `:hover` never appears for keyboard and touch users. The links inside it may even receive focus while invisible.',
  dtext='a CSS rule that shows a descendant or sibling on `:hover`, or a `mouseenter`/`mouseover` handler, with no focus or activation equivalent. The same content must also be dismissible and hoverable (see `components/tooltip.md`).',
  detect=[R(r''':hover\s*(?:>|\+|~|\s)\s*[^,{]+\{[^}]*(?:display\s*:\s*(?:block|flex|grid)|visibility\s*:\s*visible|opacity\s*:\s*1)''', target='css'),
          R(r'''\bonmouse(?:over|enter)\s*=|addEventListener\(\s*['"]mouse(?:over|enter)['"]''', target='js', unless=r'''addEventListener\(\s*['"]focus(?:in)?['"]|\bonfocus\s*=''', test=False)],
  bad='.menu li > ul { display: none; }\n.menu li:hover > ul { display: block; }',
  good='/* Opened by a button, for every input method. */\n.menu button[aria-expanded="true"] + ul { display: block; }\n.menu button[aria-expanded="false"] + ul { display: none; }'),
 dict(id='AP-KBD-04', title='Custom modal with no focus management', sev='blocking', wcag=['2.4.3', '4.1.2'], rgaa=['7.1', '12.8'], axe=['aria-dialog-name'], lang='html',
  what='A `<div>` displayed above the page takes neither focus nor the dialog role. Keyboard focus stays in the page behind the overlay, and a screen reader user is not told that anything opened. If the overlay cannot be closed with the keyboard, the page is lost.',
  dtext='a `<div>` whose class or id suggests a modal and that has no `role="dialog"`. Then check by hand: focus moves in, stays in, Escape closes, focus returns.',
  detect=[R(r'''<div\b(?![^>]*\brole\s*=\s*['"](?:dialog|alertdialog)['"])[^>]*\b(?:class|id)\s*=\s*['"][^'"]*\b(?:modal|popup|lightbox|drawer)\b''')],
  bad='<div class="modal is-open">\n  <span class="close" onclick="closeModal()">\u00d7</span>\n  <p>Subscribe to our newsletter</p>\n</div>',
  good='<dialog id="newsletter" aria-labelledby="newsletter-title">\n  <h2 id="newsletter-title">Subscribe to our newsletter</h2>\n  <form method="dialog"><button>Close</button></form>\n</dialog>\n<!-- opened on request with dialog.showModal(); see components/modal-dialog.md -->'),
 dict(id='AP-KBD-05', title='Keyboard trap', sev='blocking', wcag=['2.1.2'], rgaa=['12.9'], axe=[], lang='js',
  what='A component that captures Tab (a code editor, an embedded player, a badly written focus loop) keeps keyboard focus for good. Everything after it on the page is out of reach, and the only exit is to reload.',
  dtext='a key handler that cancels the default action of Tab. Legitimate inside a modal dialog that can be closed with Escape; a defect anywhere the person has no documented keyboard exit.',
  detect=[R(r'''(?:key|code)\s*===?\s*['"]Tab['"](?:(?!\}\s*\)).){0,200}preventDefault|keyCode\s*===?\s*9\b(?:(?!\}\s*\)).){0,200}preventDefault''', target='js', flags='s')],
  bad="editor.addEventListener('keydown', (event) => {\n  if (event.key === 'Tab') {\n    event.preventDefault();\n    insertText('\\t');\n  }\n});",
  good="// Tab keeps moving focus; indentation has its own button and shortcut.\nindentButton.addEventListener('click', () => insertText('\\t'));"),
 dict(id='AP-KBD-06', title='Focus lost when the focused element disappears', sev='major', wcag=['2.4.3'], rgaa=['7.3'], axe=[], lang='js',
  what='Deleting a row, closing a panel or re-rendering a list removes the element that had focus. Focus falls back to the top of the document: a keyboard user must travel back, and a screen reader user is silently moved elsewhere.',
  dtext='code that removes or hides a container without first checking whether it contains `document.activeElement`. Confirm by performing the action with the keyboard and pressing Tab once.',
  detect=[X('In scripts: calls to remove(), replaceChildren(), innerHTML assignment or hidden = true on a container, in a handler that does not call focus() afterwards.', target='js')],
  bad="deleteButton.addEventListener('click', () => {\n  row.remove();\n});",
  good="deleteButton.addEventListener('click', () => {\n  const next = row.nextElementSibling ?? row.previousElementSibling;\n  row.remove();\n  (next?.querySelector('button') ?? listHeading).focus();   // listHeading has tabindex=\"-1\"\n  announce('Address deleted');\n});"),
 dict(id='AP-KBD-07', title='No skip link', sev='major', wcag=['2.4.1'], rgaa=['12.7'], axe=['bypass', 'skip-link'], lang='html',
  what='Without it, a keyboard user goes through the whole header and menu on every page before reaching the content.',
  dtext='the first focusable element of `<body>` is not a link to an anchor that exists in the page.',
  detect=[X('Take the first focusable element in document order; report unless it is a[href^="#"] whose target id exists and is inside or is the main content.')],
  bad='<body>\n  <header>...</header>\n  <main>...</main>\n</body>',
  good='<body>\n  <a class="skip-link" href="#main">Skip to main content</a>\n  <header>...</header>\n  <main id="main" tabindex="-1">...</main>\n</body>'),
 dict(id='AP-KBD-08', title='Sticky bar that covers the focused element', sev='major', wcag=['2.4.11'], rgaa=[], axe=[], lang='css',
  what='When focus moves to a link that the browser scrolls just under a fixed header or footer, the person activates something they cannot see.',
  dtext='`position: sticky` or `fixed` in a style sheet that sets no `scroll-padding`. Confirm by tabbing forward and backward at 320 CSS pixels wide.',
  detect=[R(r'''position\s*:\s*(?:sticky|fixed)''', target='css', unless=r'''scroll-padding(?:-top|-bottom|-block(?:-start|-end)?)?\s*:''')],
  bad='.site-header { position: sticky; top: 0; }',
  good='.site-header { position: sticky; top: 0; }\nhtml { scroll-padding-top: 5rem; }   /* height of the header */'),
 dict(id='AP-KBD-09', title='Single-key shortcut', sev='major', wcag=['2.1.4'], rgaa=['12.10'], axe=[], lang='js',
  what='Speech recognition types what it hears. A dictated word is received as a burst of letters, each of which triggers a shortcut. Keyboard users also hit them by accident.',
  dtext='a key handler that compares the key with a single printable character without testing a modifier key. Acceptable only if the shortcut can be turned off or remapped, or works only while its component has focus.',
  detect=[R(r'''\.key\s*===?\s*['"][a-zA-Z0-9/?.,]['"](?!\s*&&\s*\(?\s*\w+\.(?:ctrlKey|metaKey|altKey))''', target='js')],
  bad="document.addEventListener('keydown', (event) => {\n  if (event.key === 's') openSearch();\n});",
  good="document.addEventListener('keydown', (event) => {\n  if (event.key === 'k' && (event.ctrlKey || event.metaKey)) {\n    event.preventDefault();\n    openSearch();\n  }\n});"),
 dict(id='AP-KBD-10', title='Scrollable area that the keyboard cannot scroll', sev='major', wcag=['2.1.1'], rgaa=['7.3'], axe=['scrollable-region-focusable'], lang='html',
  what='A block with `overflow: auto` and no focusable content cannot receive focus in every browser, so the arrow keys cannot scroll it. The end of a wide table or of a terms-and-conditions box is out of reach.',
  dtext='an element whose computed `overflow` is `auto` or `scroll`, whose content overflows, and that is not focusable and contains no focusable element.',
  detect=[X('Elements with computed overflow auto|scroll and scrollWidth > clientWidth or scrollHeight > clientHeight, without tabindex and without focusable descendants.')],
  bad='<div class="table-scroll">\n  <table>...</table>\n</div>',
  good='<div class="table-scroll" role="region" aria-labelledby="prices-caption" tabindex="0">\n  <table>\n    <caption id="prices-caption">Prices by country</caption>\n  </table>\n</div>'),
 dict(id='AP-KBD-11', title='Drag and drop as the only way', sev='blocking', wcag=['2.5.7', '2.1.1'], rgaa=['7.3'], axe=[], lang='html',
  what='Reordering, moving a card or setting a slider by dragging is impossible with a keyboard and for people who cannot hold a press while moving the pointer.',
  dtext='presence of drag handling. Then check that each dragged item also has controls that do the same with single clicks.',
  detect=[R(r'''\bdraggable\s*=\s*['"]true['"]|addEventListener\(\s*['"](?:dragstart|drop)['"]|\bnew\s+Sortable\s*\(|\bdragula\s*\(''')],
  bad='<ul id="playlist">\n  <li draggable="true">Morning news</li>\n  <li draggable="true">Weather report</li>\n</ul>',
  good='<ul id="playlist">\n  <li draggable="true">\n    Morning news\n    <button type="button" data-move="up">Move Morning news up</button>\n    <button type="button" data-move="down">Move Morning news down</button>\n  </li>\n</ul>'),
 dict(id='AP-KBD-12', title='Pointer target smaller than 24 by 24 CSS pixels', sev='major', wcag=['2.5.8'], rgaa=[], axe=['target-size'], lang='css',
  what='People with tremor, or using a finger on a phone, miss a 16-pixel icon or hit its neighbour. Close buttons, pagination, carousel dots and row actions are the usual cases.',
  dtext='a clickable element whose bounding box is under 24 pixels in width or height and whose 24-pixel circle meets another target. Links inside sentences are exempt.',
  detect=[X('For each clickable element: getBoundingClientRect() under 24 in either dimension, then apply the spacing exception of WCAG 2.5.8; skip inline links in text and unstyled native controls.')],
  bad='.close { width: 16px; height: 16px; padding: 0; }',
  good='.close {\n  min-width: 24px;\n  min-height: 24px;\n  display: inline-grid;\n  place-items: center;   /* the 16px icon is centred in a 24px target */\n}'),
 dict(id='AP-KBD-13', title='Action triggered when the pointer goes down', sev='minor', wcag=['2.5.2'], rgaa=['13.11'], axe=[], lang='js',
  what='An action that fires on `mousedown`, `pointerdown` or `touchstart` cannot be cancelled by sliding off the control before releasing. People with tremor trigger things by brushing the screen.',
  dtext='handlers on down-events. Fine when they only prepare something (keeping focus, starting a drag that can be aborted) and the action itself happens on `click`.',
  detect=[R(r'''\bon(?:mousedown|touchstart|pointerdown)\s*=|addEventListener\(\s*['"](?:mousedown|touchstart|pointerdown)['"]''', target='js')],
  bad="deleteButton.addEventListener('mousedown', deleteItem);",
  good="deleteButton.addEventListener('click', deleteItem);"),
]

FORMS = [
 dict(id='AP-FRM-01', title='Field without a label', sev='blocking', wcag=['3.3.2', '4.1.2'], rgaa=['11.1'], axe=['label', 'select-name'], lang='html',
  what='The screen reader announces "edit text" with no subject. Voice control cannot target the field. Clicking the nearby text does not put focus in the field.',
  dtext='a form control with no `id` (so no `<label for>` can point to it) and no `aria-label`, `aria-labelledby` or `title`, unless it is wrapped in a `<label>`. A DOM checker computes the accessible name instead.',
  detect=[X('input, select, textarea (except hidden, submit, button, reset, image) whose computed accessible name is empty.'),
          R(r'''<(?:input|select|textarea)\b(?![^>]*\b(?:id|aria-label|aria-labelledby|title)\s*=)(?![^>]*\btype\s*=\s*['"](?:hidden|submit|button|reset|image|checkbox|radio)['"])[^>]*>''')],
  bad='<input type="text" name="lastname">',
  good='<label for="lastname">Last name</label>\n<input id="lastname" name="lastname" type="text" autocomplete="family-name">'),
 dict(id='AP-FRM-02', title='Placeholder used as the label', sev='major', wcag=['3.3.2'], rgaa=['11.1', '11.4'], axe=[], lang='html',
  what='The instruction disappears at the first character typed. People who are interrupted, or who have memory or attention difficulties, no longer know what the field expects; default placeholder contrast is low; the field cannot be checked once filled.',
  dtext='a field that has a `placeholder` and an `aria-label` but no `id` for a visible `<label>`: its only visible text is the placeholder.',
  detect=[R(r'''<(?:input|textarea)\b(?=[^>]*\bplaceholder\s*=)(?=[^>]*\baria-label\s*=)(?![^>]*\bid\s*=)[^>]*>''')],
  bad='<input type="email" name="email" placeholder="Your email" aria-label="Your email">',
  good='<label for="email">Email address</label>\n<p id="email-hint">For example: name@example.org</p>\n<input id="email" name="email" type="email" autocomplete="email" aria-describedby="email-hint">'),
 dict(id='AP-FRM-03', title='`<label>` not tied to its field', sev='blocking', wcag=['3.3.2', '4.1.2'], rgaa=['11.1'], axe=['label'], lang='html',
  what='The label is on screen but nothing links it to the field in code, so the field has no name for assistive technology. Frequent when `for` and `id` do not match, or in JSX when `for` is written instead of `htmlFor`.',
  dtext='a `<label>` with no `for` (or `htmlFor`) that does not contain a form control; and, in a DOM checker, a `for` value that matches no `id`.',
  detect=[R(r'''<label\b(?![^>]*\b(?:html)?for\s*=)[^>]*>(?:(?!</label>|<input|<select|<textarea).)*</label>''', flags='is')],
  bad='<label>Phone number</label>\n<input type="tel" name="phone">',
  good='<label for="phone">Phone number</label>\n<input id="phone" name="phone" type="tel" autocomplete="tel">'),
 dict(id='AP-FRM-04', title='Error shown by style only, or not tied to its field', sev='major', wcag=['3.3.1'], rgaa=['11.10'], axe=[], lang='html',
  what='A red border is invisible to people who do not see that colour and silent for a screen reader. A message placed nearby but not linked in code is not read when the person returns to the field.',
  dtext='a field with an "error" or "invalid" class and no `aria-invalid`. Then check that the message is text, names the field and is referenced by `aria-describedby`.',
  detect=[R(r'''<(?:input|select|textarea)\b(?![^>]*aria-invalid)[^>]*\bclass\s*=\s*['"][^'"]*\b(?:error|invalid|is-invalid|has-error)\b''')],
  bad='<label for="zip">Postal code</label>\n<input id="zip" name="zip" class="input is-invalid">\n<span class="red">!</span>',
  good='<label for="zip">Postal code</label>\n<input id="zip" name="zip" autocomplete="postal-code" aria-invalid="true" aria-describedby="zip-error">\n<p id="zip-error">Error: enter the 5 digits of the postal code, for example 75011</p>'),
 dict(id='AP-FRM-05', title='Required field marked by an asterisk or a colour only', sev='major', wcag=['3.3.2'], rgaa=['11.10'], axe=[], lang='html',
  what='An unexplained asterisk means nothing to someone who does not know the convention, and a colour is not announced. Without `required` or `aria-required`, a screen reader does not say that the field is mandatory.',
  dtext='a label containing `*` followed by a field with neither `required` nor `aria-required`.',
  detect=[R(r'''<label\b[^>]*>(?:(?!</label>).)*\*(?:(?!</label>).)*</label>\s*<(?:input|select|textarea)\b(?![^>]*(?:\srequired(?=[\s>=/])|aria-required))[^>]*>''', flags='is')],
  bad='<label for="name">Name <span class="red">*</span></label>\n<input id="name" name="name" type="text">',
  good='<label for="name">Name (required)</label>\n<input id="name" name="name" type="text" autocomplete="name" required>'),
 dict(id='AP-FRM-06', title='Personal data field without `autocomplete`', sev='minor', wcag=['1.3.5'], rgaa=['11.13'], axe=['autocomplete-valid'], lang='html',
  what='The browser cannot fill the field. People for whom typing is slow or error-prone (switch, voice, tremor, dyslexia) must enter each value by hand, on every site.',
  dtext='an `<input>` whose `name`, `id` or `type` denotes a piece of information about the user and that has no `autocomplete` attribute.',
  detect=[R(r'''<input\b(?![^>]*\bautocomplete\s*=)[^>]*\b(?:name|id|type)\s*=\s*['"](?:e-?mail|tel|phone|first_?name|last_?name|given-name|family-name|name|address|street|postal_?code|zip|city|country|password|bday|birth(?:day|date)?|cc-?number)['"]''')],
  bad='<label for="email">Email address</label>\n<input id="email" name="email" type="email">',
  good='<label for="email">Email address</label>\n<input id="email" name="email" type="email" autocomplete="email">'),
 dict(id='AP-FRM-07', title='Paste or password manager blocked', sev='blocking', wcag=['3.3.8'], rgaa=[], axe=[], conf='certain', lang='html',
  what='Blocking paste or autofill forces the person to memorise and type a password or a code. People who cannot do that reliably cannot sign in at all.',
  dtext='a `paste` handler that cancels the event, or `autocomplete="off"` on a password field.',
  detect=[R(r'''\bonpaste\s*=\s*['"][^'"]*(?:return\s+false|preventDefault)|<input\b(?=[^>]*\btype\s*=\s*['"]password['"])(?=[^>]*\bautocomplete\s*=\s*['"]off['"])'''),
          R(r'''addEventListener\(\s*['"]paste['"](?:(?!\}\s*\)).){0,200}preventDefault''', target='js', flags='s', test=False)],
  bad='<label for="pwd">Password</label>\n<input id="pwd" name="password" type="password" autocomplete="off" onpaste="return false">',
  good='<label for="pwd">Password</label>\n<input id="pwd" name="password" type="password" autocomplete="current-password">'),
 dict(id='AP-FRM-08', title='One input box per character', sev='major', wcag=['3.3.8'], rgaa=[], axe=[], lang='html',
  what='A code split over four or six boxes cannot be pasted or autofilled in one go. Each box is announced without a meaningful label, and focus that jumps by itself disorients screen reader and magnifier users.',
  dtext='three or more consecutive inputs with `maxlength="1"`.',
  detect=[R(r'''(?:<input\b[^>]*\bmaxlength\s*=\s*['"]?1['"]?[^>]*>\s*){3,}''')],
  bad='<input maxlength="1" name="c1"> <input maxlength="1" name="c2">\n<input maxlength="1" name="c3"> <input maxlength="1" name="c4">',
  good='<label for="otp">Code received by text message (6 digits)</label>\n<input id="otp" name="otp" type="text" inputmode="numeric" autocomplete="one-time-code">'),
 dict(id='AP-FRM-09', title='Radio buttons or checkboxes without a group label', sev='major', wcag=['1.3.1'], rgaa=['11.5', '11.6'], axe=[], lang='html',
  what='The question is displayed above the options but is not part of any of them. A screen reader reads "Yes, radio button, 1 of 2" without the question.',
  dtext='radio buttons that are not inside a `<fieldset>` with a `<legend>`, nor inside a named `role="group"` or `role="radiogroup"`.',
  detect=[S('input[type="radio"]:not(fieldset input):not([role="radiogroup"] input):not([role="group"] input)')],
  bad='<p>Do you have a customer account?</p>\n<label><input type="radio" name="account" value="yes"> Yes</label>\n<label><input type="radio" name="account" value="no"> No</label>',
  good='<fieldset>\n  <legend>Do you have a customer account?</legend>\n  <label><input type="radio" name="account" value="yes"> Yes</label>\n  <label><input type="radio" name="account" value="no"> No</label>\n</fieldset>'),
 dict(id='AP-FRM-10', title='Field that navigates or submits when its value changes', sev='major', wcag=['3.2.2'], rgaa=['7.4'], axe=[], lang='html',
  what='A keyboard user browsing a `<select>` with the arrow keys changes its value at each press: the page leaves on the first option. A screen reader user gets a new page without having asked for one.',
  dtext='a `change` handler that sets the location, submits a form or opens a window.',
  detect=[R(r'''<select\b[^>]*\bonchange\s*=\s*['"][^'"]*(?:location|submit\s*\(|window\.open|navigate)'''),
          R(r'''addEventListener\(\s*['"]change['"](?:(?!\}\s*\)).){0,200}(?:location\.(?:href|assign)|\.submit\s*\()''', target='js', flags='s', test=False)],
  bad='<label for="lang">Language</label>\n<select id="lang" onchange="location = this.value">\n  <option value="/fr">Fran\u00e7ais</option>\n  <option value="/en">English</option>\n</select>',
  good='<form action="/language" method="get">\n  <label for="lang">Language</label>\n  <select id="lang" name="lang">\n    <option value="fr" lang="fr">Fran\u00e7ais</option>\n    <option value="en" lang="en">English</option>\n  </select>\n  <button type="submit">Change language</button>\n</form>'),
 dict(id='AP-FRM-11', title='Submit button disabled until the form is valid', sev='minor', wcag=[], rgaa=[], axe=[], lang='html',
  what='A disabled button cannot be focused and gives no reason. The person does not learn which field is missing or wrong, and low-contrast disabled styling makes the button hard to see at all.',
  dtext='a submit button rendered with `disabled`. Prefer an enabled button and errors explained on submission.',
  detect=[R(r'''<button\b(?=[^>]*\btype\s*=\s*['"]submit['"])(?=[^>]*\sdisabled(?=[\s>=/]))''')],
  bad='<button type="submit" disabled>Create my account</button>',
  good='<button type="submit">Create my account</button>\n<!-- on submit: list the errors and move focus to the summary (components/multi-step-form.md) -->'),
 dict(id='AP-FRM-12', title='Error message that does not say how to fix the error', sev='major', wcag=['3.3.3'], rgaa=['11.11'], axe=[], lang='html',
  what='"Invalid input" names neither the field nor the expected value. The person tries again at random; each attempt costs more to someone who types slowly or with a switch.',
  dtext='a text node that is only a generic error phrase. Whether any other message is helpful needs a person.',
  detect=[R(r'''>\s*(?:invalid(?: input| value| field| format| entry)?|error|required|this field is required|field required|champ invalide|erreur|champ obligatoire|saisie invalide)\s*[.!]?\s*<''')],
  bad='<p class="error">Invalid input</p>',
  good='<p id="phone-error">Error: enter a phone number with 10 digits, for example 06 12 34 56 78</p>'),
 dict(id='AP-FRM-13', title='Native control hidden with `display: none` behind a custom one', sev='blocking', wcag=['2.1.1', '4.1.2'], rgaa=['7.3', '7.1'], axe=[], conf='certain', lang='css',
  what='A checkbox, radio button or file input hidden with `display: none` or `visibility: hidden` leaves the Tab sequence and the accessibility tree. The styled replacement is a picture of a control: it cannot be focused or operated with the keyboard.',
  dtext='a CSS rule that hides a checkbox, radio or file input with `display: none` or `visibility: hidden`.',
  detect=[R(r'''input\[type=['"]?(?:checkbox|radio|file)['"]?\][^{]*\{[^}]*(?:display\s*:\s*none|visibility\s*:\s*hidden)''', target='css')],
  bad='input[type="checkbox"] { display: none; }\ninput[type="checkbox"] + label::before { content: ""; /* drawn box */ }',
  good='/* The real checkbox stays focusable; it is only made invisible. */\ninput[type="checkbox"].custom {\n  position: absolute;\n  opacity: 0;\n  width: 1.5rem;\n  height: 1.5rem;\n}\ninput[type="checkbox"].custom:focus-visible + label::before { outline: 3px solid currentColor; outline-offset: 2px; }'),
 dict(id='AP-FRM-14', title='CAPTCHA with no alternative', sev='blocking', wcag=['1.1.1', '3.3.8'], rgaa=['1.5'], axe=[], lang='html',
  what='Distorted text, image grids, sliders and audio challenges each lock out people who cannot see, hear, solve or perform them. With no other route, the function behind the CAPTCHA is closed to them.',
  dtext='presence of a CAPTCHA component. Then check by hand which challenges it can show and whether a route with no challenge exists (see `fallbacks.md`).',
  detect=[R(r'''\b(?:g-recaptcha|h-captcha|cf-turnstile|captcha)\b''')],
  bad='<img src="/captcha.png" alt="CAPTCHA">\n<input name="captcha">',
  good='<!-- No challenge shown: rate limiting and a hidden trap field on the server side, -->\n<!-- and confirmation of the request by a link sent by email. -->\n<button type="submit">Send the request</button>'),
 dict(id='AP-FRM-15', title='Session that expires without warning', sev='major', wcag=['2.2.1'], rgaa=['13.1'], axe=[], lang='js',
  what='People who read, type or navigate slowly are signed out in the middle of a form and lose what they entered.',
  dtext='a timer that signs out or redirects. Then check that a warning with a way to extend comes first.',
  detect=[R(r'''setTimeout\s*\((?:(?!setTimeout).){0,200}?(?:logout|log-out|sign-?out|expire)''', target='js', flags='is')],
  bad="setTimeout(() => { window.location.href = '/logout'; }, 15 * 60 * 1000);",
  good="// Two minutes before the limit, a dialog offers to stay signed in.\nsetTimeout(() => document.getElementById('session-warning').showModal(), 13 * 60 * 1000);\nstayButton.addEventListener('click', () => fetch('/session/extend', { method: 'POST' }));"),
 dict(id='AP-FRM-16', title='Asking again for information already given', sev='major', wcag=['3.3.7'], rgaa=[], axe=[], lang='html',
  what='Typing an email address twice, or a billing address identical to the delivery address, is one more occasion for error and fatigue for people with memory or motor difficulties.',
  dtext='a "confirm" field for a value that is displayed in clear, or the same field names repeated across the steps of one process with no pre-filling. A new password that is not displayed may be asked twice.',
  detect=[R(r'''\bname\s*=\s*['"](?:confirm_?e?-?mail|e?-?mail_?confirm(?:ation)?|e?-?mail2|repeat_?e?-?mail)['"]''')],
  bad='<label for="email">Email address</label>\n<input id="email" name="email" type="email" autocomplete="email">\n<label for="email2">Confirm your email address</label>\n<input id="email2" name="email_confirmation" type="email">',
  good='<label for="email">Email address</label>\n<input id="email" name="email" type="email" autocomplete="email">\n<!-- The address is shown again for checking at the review step, with a "Change" link. -->'),
]
